-- ============================================================
insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000002101', 'it is essential that', '/ɪt ɪz ɪˈsenʃəl ðæt/', 'phrase', 'é essencial que', 'It is essential that he attend the meeting.', 'É essencial que ele compareça à reunião.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002102', 'it is important that', '/ɪt ɪz ɪmˈpɔːrtənt ðæt/', 'phrase', 'é importante que', 'It is important that she be informed immediately.', 'É importante que ela seja informada imediatamente.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002103', 'crucial', '/ˈkruːʃəl/', 'adjective', 'crucial', 'Clear communication is crucial for the project to succeed.', 'Uma comunicação clara é crucial para o sucesso do projeto.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002104', 'imperative', '/ɪmˈperətɪv/', 'adjective', 'imperativo, essencial', 'It is imperative that we finish before the deadline.', 'É imperativo que terminemos antes do prazo.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002105', 'mandatory', '/ˈmændətɔːri/', 'adjective', 'obrigatório', 'Attendance at the training session is mandatory.', 'A presença na sessão de treinamento é obrigatória.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002106', 'vital', '/ˈvaɪtl/', 'adjective', 'vital', 'It is vital that the data remain confidential.', 'É vital que os dados permaneçam confidenciais.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002107', 'recommend that', '/ˌrekəˈmend ðæt/', 'phrase', 'recomendar que', 'The doctor recommended that he rest for a week.', 'O médico recomendou que ele descansasse por uma semana.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002108', 'suggest that', '/səˈdʒest ðæt/', 'phrase', 'sugerir que', 'I suggest that she review the contract again.', 'Eu sugiro que ela revise o contrato novamente.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002109', 'insist that', '/ɪnˈsɪst ðæt/', 'phrase', 'insistir que', 'The manager insisted that the report be finished today.', 'O gerente insistiu que o relatório fosse terminado hoje.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002110', 'demand that', '/dɪˈmænd ðæt/', 'phrase', 'exigir que', 'The client demanded that the issue be resolved immediately.', 'O cliente exigiu que o problema fosse resolvido imediatamente.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002111', 'require that', '/rɪˈkwaɪər ðæt/', 'phrase', 'exigir, requerer que', 'The policy requires that all staff wear identification badges.', 'A política exige que todos os funcionários usem crachás de identificação.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002112', 'propose that', '/prəˈpoʊz ðæt/', 'phrase', 'propor que', 'I propose that we postpone the meeting until next week.', 'Eu proponho que adiemos a reunião para a próxima semana.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002113', 'request that', '/rɪˈkwest ðæt/', 'phrase', 'solicitar que', 'We request that you submit the form by Friday.', 'Solicitamos que você envie o formulário até sexta-feira.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002114', 'advise that', '/ədˈvaɪz ðæt/', 'phrase', 'aconselhar que', 'The lawyer advised that she sign the document carefully.', 'O advogado aconselhou que ela assinasse o documento com cuidado.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002115', 'advisable', '/ədˈvaɪzəbəl/', 'adjective', 'aconselhável', 'It is advisable that you keep a copy of every contract.', 'É aconselhável que você guarde uma cópia de cada contrato.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002116', 'preferable', '/ˈprefərəbəl/', 'adjective', 'preferível', 'It is preferable that the meeting take place in the morning.', 'É preferível que a reunião aconteça de manhã.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002117', 'would rather', '/wʊd ˈræðər/', 'phrase', 'preferiria que', 'I would rather you called before visiting.', 'Eu preferiria que você ligasse antes de visitar.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002118', 'suppose that', '/səˈpoʊz ðæt/', 'phrase', 'suponha que', 'Suppose that the plan fails; what would we do next?', 'Suponha que o plano falhe; o que faríamos em seguida?', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002119', 'lest', '/lest/', 'conjunction', 'para que não', 'She double-checked the numbers lest there be a mistake.', 'Ela conferiu os números novamente para que não houvesse um erro.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002120', 'so that', '/soʊ ðæt/', 'conjunction', 'para que', 'He arrived early so that he could prepare the room.', 'Ele chegou cedo para que pudesse preparar a sala.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002121', 'in order that', '/ɪn ˈɔːrdər ðæt/', 'conjunction', 'a fim de que', 'The rules were changed in order that everyone be treated fairly.', 'As regras foram mudadas a fim de que todos fossem tratados de forma justa.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002122', 'for fear that', '/fɔːr fɪər ðæt/', 'phrase', 'com medo de que', 'She avoided the topic for fear that it might cause conflict.', 'Ela evitou o assunto com medo de que causasse conflito.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002123', 'as if', '/æz ɪf/', 'conjunction', 'como se', 'He spoke as if he were the manager.', 'Ele falou como se fosse o gerente.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002124', 'as though', '/æz ðoʊ/', 'conjunction', 'como se', 'She looked at the report as though something were wrong.', 'Ela olhou para o relatório como se algo estivesse errado.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002125', 'wish', '/wɪʃ/', 'verb', 'desejar, gostaria que', 'I wish I were more confident during presentations.', 'Eu gostaria de ser mais confiante durante apresentações.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002126', 'if only', '/ɪf ˈoʊnli/', 'phrase', 'se ao menos', 'If only she had more time, she would finish the project.', 'Se ao menos ela tivesse mais tempo, terminaria o projeto.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002127', 'it''s high time', '/ɪts haɪ taɪm/', 'phrase', 'já está mais que na hora', 'It''s high time the company updated its policies.', 'Já está mais que na hora de a empresa atualizar suas políticas.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002128', 'were to', '/wɜːr tuː/', 'phrase', 'se... viesse a', 'If the deadline were to change, we would notify everyone.', 'Se o prazo viesse a mudar, avisaríamos todo mundo.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002129', 'be it', '/biː ɪt/', 'phrase', 'seja', 'Any solution, be it simple or complex, must be approved first.', 'Qualquer solução, seja simples ou complexa, precisa ser aprovada primeiro.', 'C1', array['subjunctive']),
('30000000-0000-0000-0000-000000002130', 'formal register', '/ˈfɔːrməl ˈredʒɪstər/', 'noun', 'registro formal', 'Business emails usually require a formal register.', 'E-mails corporativos geralmente exigem um registro formal.', 'C1', array['subjunctive']);

