-- Lição 351: Adjetivos de necessidade (it is essential that, it is important that, crucial, imperative, mandatory, vital)
insert into exercises (lesson_id, type, sort_order, content) values
('20000000-0000-0000-0000-000000000351', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002101", "show_image": false}'),
('20000000-0000-0000-0000-000000000351', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002104", "show_image": false}'),
('20000000-0000-0000-0000-000000000351', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002105", "show_image": false}'),
('20000000-0000-0000-0000-000000000351', 'multiple_choice', 4, '{"question": "It is essential that he ___ the meeting.", "audio_text": null, "options": ["attend", "attends", "attended"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000351', 'multiple_choice', 5, '{"question": "Attendance at the training session is ___.", "audio_text": null, "options": ["mandatory", "preferable", "arguably"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000351', 'matching', 6, '{"pairs": [{"left": "it is essential that", "right": "é essencial que"}, {"left": "it is important that", "right": "é importante que"}, {"left": "crucial", "right": "crucial"}, {"left": "imperative", "right": "imperativo, essencial"}, {"left": "mandatory", "right": "obrigatório"}, {"left": "vital", "right": "vital"}]}'),
('20000000-0000-0000-0000-000000000351', 'fill_blank', 7, '{"sentence": "It is ___ that we finish before the deadline.", "options": ["imperative", "advisable", "questionable"], "correct": "imperative", "translation": "É imperativo que terminemos antes do prazo."}'),
('20000000-0000-0000-0000-000000000351', 'fill_blank', 8, '{"sentence": "It is ___ that the data remain confidential.", "options": ["vital", "mandatory", "preferable"], "correct": "vital", "translation": "É vital que os dados permaneçam confidenciais."}'),
('20000000-0000-0000-0000-000000000351', 'word_order', 9, '{"words": ["It", "is", "important", "that", "she", "be", "informed", "immediately"], "correct_sentence": "It is important that she be informed immediately", "translation": "É importante que ela seja informada imediatamente"}'),
('20000000-0000-0000-0000-000000000351', 'word_order', 10, '{"words": ["Clear", "communication", "is", "crucial", "for", "the", "project", "to", "succeed"], "correct_sentence": "Clear communication is crucial for the project to succeed", "translation": "Uma comunicação clara é crucial para o sucesso do projeto"}'),
('20000000-0000-0000-0000-000000000351', 'reading', 11, '{"passage": "In formal English, adjectives like ''essential'', ''important'', ''imperative'' and ''vital'' are often followed by ''that'' plus the base form of the verb, without ''-s'' or a modal. This structure, called the subjunctive, sounds more formal than using ''should''. For example, ''it is essential that he attend'' is more formal than ''he should attend''.", "translation": "No inglês formal, adjetivos como ''essential'', ''important'', ''imperative'' e ''vital'' costumam ser seguidos por ''that'' mais a forma base do verbo, sem ''-s'' ou modal. Essa estrutura, chamada de subjuntivo, soa mais formal do que usar ''should''. Por exemplo, ''it is essential that he attend'' é mais formal do que ''he should attend''.", "question": "According to the text, what form of the verb follows ''that'' in this structure?", "options": ["The base form, without ''-s''", "The past tense", "The ''-ing'' form"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000351', 'listening', 12, '{"audio_text": "It is essential that he attend the meeting. Attendance at the training session is mandatory. It is vital that the data remain confidential.", "question": "What is mandatory, according to the audio?", "options": ["Attendance at the training session", "Attending the meeting", "Keeping the data confidential"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000351', 'dictation', 13, '{"audio_text": "It is essential that he attend the meeting.", "expected": "It is essential that he attend the meeting."}'),
('20000000-0000-0000-0000-000000000351', 'typing', 14, '{"prompt_pt": "Traduza: ''É essencial que ela esteja presente; é imperativo que o relatório permaneça confidencial.''", "expected": "It is essential that she be present; it is imperative that the report remain confidential.", "ai_review": true}'),

-- Lição 352: Verbos de recomendação e exigência (recommend that, suggest that, insist that, demand that, require that, propose that)
('20000000-0000-0000-0000-000000000352', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002107", "show_image": false}'),
('20000000-0000-0000-0000-000000000352', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002109", "show_image": false}'),
('20000000-0000-0000-0000-000000000352', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002112", "show_image": false}'),
('20000000-0000-0000-0000-000000000352', 'multiple_choice', 4, '{"question": "The doctor recommended that he ___ for a week.", "audio_text": null, "options": ["rest", "rests", "rested"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000352', 'multiple_choice', 5, '{"question": "The manager insisted that the report ___ finished today.", "audio_text": null, "options": ["be", "is", "was"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000352', 'matching', 6, '{"pairs": [{"left": "recommend that", "right": "recomendar que"}, {"left": "suggest that", "right": "sugerir que"}, {"left": "insist that", "right": "insistir que"}, {"left": "demand that", "right": "exigir que"}, {"left": "require that", "right": "exigir, requerer que"}, {"left": "propose that", "right": "propor que"}]}'),
('20000000-0000-0000-0000-000000000352', 'fill_blank', 7, '{"sentence": "The client demanded that the issue ___ resolved immediately.", "options": ["be", "is", "was"], "correct": "be", "translation": "O cliente exigiu que o problema fosse resolvido imediatamente."}'),
('20000000-0000-0000-0000-000000000352', 'fill_blank', 8, '{"sentence": "The policy requires that all staff ___ identification badges.", "options": ["wear", "wears", "wore"], "correct": "wear", "translation": "A política exige que todos os funcionários usem crachás de identificação."}'),
('20000000-0000-0000-0000-000000000352', 'word_order', 9, '{"words": ["I", "suggest", "that", "she", "review", "the", "contract", "again"], "correct_sentence": "I suggest that she review the contract again", "translation": "Eu sugiro que ela revise o contrato novamente"}'),
('20000000-0000-0000-0000-000000000352', 'word_order', 10, '{"words": ["I", "propose", "that", "we", "postpone", "the", "meeting", "until", "next", "week"], "correct_sentence": "I propose that we postpone the meeting until next week", "translation": "Eu proponho que adiemos a reunião para a próxima semana"}'),
('20000000-0000-0000-0000-000000000352', 'reading', 11, '{"passage": "Verbs like ''recommend'', ''suggest'', ''insist'', ''demand'', ''require'' and ''propose'' trigger the same subjunctive pattern: verb + that + subject + base form. A doctor might recommend that a patient rest, while a client might demand that an issue be resolved. This pattern is common in formal writing, contracts and professional emails.", "translation": "Verbos como ''recommend'', ''suggest'', ''insist'', ''demand'', ''require'' e ''propose'' ativam o mesmo padrão de subjuntivo: verbo + that + sujeito + forma base. Um médico pode recomendar que um paciente descanse, enquanto um cliente pode exigir que um problema seja resolvido. Esse padrão é comum em textos formais, contratos e e-mails profissionais.", "question": "Where is this subjunctive pattern common, according to the text?", "options": ["Only in spoken slang", "In formal writing, contracts and professional emails", "Only in poetry"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000352', 'listening', 12, '{"audio_text": "The doctor recommended that he rest for a week. The manager insisted that the report be finished today. I propose that we postpone the meeting until next week.", "question": "What did the manager insist on, according to the audio?", "options": ["Postponing the meeting", "Finishing the report today", "Resting for a week"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000352', 'dictation', 13, '{"audio_text": "The manager insisted that the report be finished today.", "expected": "The manager insisted that the report be finished today."}'),
('20000000-0000-0000-0000-000000000352', 'typing', 14, '{"prompt_pt": "Traduza: ''Eu sugiro que ela revise o contrato, mas o cliente exige que seja assinado hoje.''", "expected": "I suggest that she review the contract, but the client demands that it be signed today.", "ai_review": true}'),

-- Lição 353: Pedidos, preferências e suposições (request that, advise that, advisable, preferable, would rather, suppose that)
('20000000-0000-0000-0000-000000000353', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002113", "show_image": false}'),
('20000000-0000-0000-0000-000000000353', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002117", "show_image": false}'),
('20000000-0000-0000-0000-000000000353', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002118", "show_image": false}'),
('20000000-0000-0000-0000-000000000353', 'multiple_choice', 4, '{"question": "We request that you ___ the form by Friday.", "audio_text": null, "options": ["submit", "submits", "submitted"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000353', 'multiple_choice', 5, '{"question": "It is ___ that you keep a copy of every contract.", "audio_text": null, "options": ["advisable", "mandatory", "debatable"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000353', 'matching', 6, '{"pairs": [{"left": "request that", "right": "solicitar que"}, {"left": "advise that", "right": "aconselhar que"}, {"left": "advisable", "right": "aconselhável"}, {"left": "preferable", "right": "preferível"}, {"left": "would rather", "right": "preferiria que"}, {"left": "suppose that", "right": "suponha que"}]}'),
('20000000-0000-0000-0000-000000000353', 'fill_blank', 7, '{"sentence": "It is ___ that the meeting take place in the morning.", "options": ["preferable", "mandatory", "questionable"], "correct": "preferable", "translation": "É preferível que a reunião aconteça de manhã."}'),
('20000000-0000-0000-0000-000000000353', 'fill_blank', 8, '{"sentence": "I ___ you called before visiting.", "options": ["would rather", "suppose that", "advise that"], "correct": "would rather", "translation": "Eu preferiria que você ligasse antes de visitar."}'),
('20000000-0000-0000-0000-000000000353', 'word_order', 9, '{"words": ["The", "lawyer", "advised", "that", "she", "sign", "the", "document", "carefully"], "correct_sentence": "The lawyer advised that she sign the document carefully", "translation": "O advogado aconselhou que ela assinasse o documento com cuidado"}'),
('20000000-0000-0000-0000-000000000353', 'word_order', 10, '{"words": ["Suppose", "that", "the", "plan", "fails", "what", "would", "we", "do", "next"], "correct_sentence": "Suppose that the plan fails what would we do next", "translation": "Suponha que o plano falhe; o que faríamos em seguida?"}'),
('20000000-0000-0000-0000-000000000353', 'reading', 11, '{"passage": "Formal requests and preferences also use special structures. ''Request that'' and ''advise that'' follow the subjunctive pattern, while ''would rather'' is followed by the past tense when talking about someone else''s actions, as in ''I would rather you called''. ''Suppose that'' introduces a hypothetical scenario for discussion, common in academic and business contexts.", "translation": "Pedidos formais e preferências também usam estruturas especiais. ''Request that'' e ''advise that'' seguem o padrão de subjuntivo, enquanto ''would rather'' é seguido pelo passado quando se fala das ações de outra pessoa, como em ''I would rather you called''. ''Suppose that'' introduz um cenário hipotético para discussão, comum em contextos acadêmicos e de negócios.", "question": "What tense follows ''would rather'' when talking about someone else''s actions, according to the text?", "options": ["The present tense", "The past tense", "The future tense"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000353', 'listening', 12, '{"audio_text": "We request that you submit the form by Friday. It is advisable that you keep a copy of every contract. I would rather you called before visiting.", "question": "By when should the form be submitted, according to the audio?", "options": ["Monday", "Friday", "Next week"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000353', 'dictation', 13, '{"audio_text": "It is advisable that you keep a copy of every contract.", "expected": "It is advisable that you keep a copy of every contract."}'),
('20000000-0000-0000-0000-000000000353', 'typing', 14, '{"prompt_pt": "Traduza: ''Solicitamos que você envie o formulário; é aconselhável que guarde uma cópia.''", "expected": "We request that you submit the form; it is advisable that you keep a copy.", "ai_review": true}'),

