('20000000-0000-0000-0000-000000000354', 'multiple_choice', 5, '{"question": "She double-checked the numbers ___ there be a mistake.", "audio_text": null, "options": ["lest", "as though", "in order that"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000354', 'matching', 6, '{"pairs": [{"left": "lest", "right": "para que não"}, {"left": "so that", "right": "para que"}, {"left": "in order that", "right": "a fim de que"}, {"left": "for fear that", "right": "com medo de que"}, {"left": "as if", "right": "como se"}, {"left": "as though", "right": "como se"}]}'),
('20000000-0000-0000-0000-000000000354', 'fill_blank', 7, '{"sentence": "He arrived early ___ he could prepare the room.", "options": ["so that", "lest", "as if"], "correct": "so that", "translation": "Ele chegou cedo para que pudesse preparar a sala."}'),
('20000000-0000-0000-0000-000000000354', 'fill_blank', 8, '{"sentence": "She avoided the topic ___ it might cause conflict.", "options": ["for fear that", "so that", "as though"], "correct": "for fear that", "translation": "Ela evitou o assunto com medo de que causasse conflito."}'),
('20000000-0000-0000-0000-000000000354', 'word_order', 9, '{"words": ["The", "rules", "were", "changed", "in", "order", "that", "everyone", "be", "treated", "fairly"], "correct_sentence": "The rules were changed in order that everyone be treated fairly", "translation": "As regras foram mudadas a fim de que todos fossem tratados de forma justa"}'),
('20000000-0000-0000-0000-000000000354', 'word_order', 10, '{"words": ["She", "looked", "at", "the", "report", "as", "though", "something", "were", "wrong"], "correct_sentence": "She looked at the report as though something were wrong", "translation": "Ela olhou para o relatório como se algo estivesse errado"}'),
('20000000-0000-0000-0000-000000000354', 'reading', 11, '{"passage": "Formal purpose clauses like ''so that'', ''in order that'' and ''lest'' explain why something is done, with ''lest'' being the most formal and often paired with the subjunctive, as in ''lest there be a mistake''. ''As if'' and ''as though'' introduce hypothetical comparisons and are typically followed by a past or subjunctive form, even when talking about the present, as in ''he spoke as if he were the manager''.", "translation": "Orações formais de propósito como ''so that'', ''in order that'' e ''lest'' explicam por que algo é feito, sendo ''lest'' a mais formal, geralmente combinada com o subjuntivo, como em ''lest there be a mistake''. ''As if'' e ''as though'' introduzem comparações hipotéticas e costumam ser seguidas por uma forma no passado ou subjuntivo, mesmo falando do presente, como em ''he spoke as if he were the manager''.", "question": "Which word is described as the most formal purpose conjunction in the text?", "options": ["So that", "Lest", "As if"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000354', 'listening', 12, '{"audio_text": "She double-checked the numbers lest there be a mistake. He spoke as if he were the manager. She looked at the report as though something were wrong.", "question": "Why did she double-check the numbers, according to the audio?", "options": ["Lest there be a mistake", "Because she was the manager", "Because something was wrong"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000354', 'dictation', 13, '{"audio_text": "He spoke as if he were the manager.", "expected": "He spoke as if he were the manager."}'),
('20000000-0000-0000-0000-000000000354', 'typing', 14, '{"prompt_pt": "Traduza: ''Ela chegou cedo para que pudesse se preparar, como se já soubesse o que aconteceria.''", "expected": "She arrived early so that she could prepare, as if she already knew what would happen.", "ai_review": true}'),

