('20000000-0000-0000-0000-000000000355', 'multiple_choice', 4, '{"question": "I wish I ___ more confident during presentations.", "audio_text": null, "options": ["were", "am", "was being"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000355', 'multiple_choice', 5, '{"question": "___ the company updated its policies.", "audio_text": null, "options": ["It''s high time", "As if", "Lest"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000355', 'matching', 6, '{"pairs": [{"left": "wish", "right": "desejar, gostaria que"}, {"left": "if only", "right": "se ao menos"}, {"left": "it''s high time", "right": "já está mais que na hora"}, {"left": "were to", "right": "se... viesse a"}, {"left": "be it", "right": "seja"}, {"left": "formal register", "right": "registro formal"}]}'),
('20000000-0000-0000-0000-000000000355', 'fill_blank', 7, '{"sentence": "If the deadline ___ change, we would notify everyone.", "options": ["were to", "will", "was"], "correct": "were to", "translation": "Se o prazo viesse a mudar, avisaríamos todo mundo."}'),
('20000000-0000-0000-0000-000000000355', 'fill_blank', 8, '{"sentence": "Any solution, ___ simple or complex, must be approved first.", "options": ["be it", "as if", "lest"], "correct": "be it", "translation": "Qualquer solução, seja simples ou complexa, precisa ser aprovada primeiro."}'),
('20000000-0000-0000-0000-000000000355', 'word_order', 9, '{"words": ["If", "only", "she", "had", "more", "time", "she", "would", "finish", "the", "project"], "correct_sentence": "If only she had more time she would finish the project", "translation": "Se ao menos ela tivesse mais tempo, terminaria o projeto"}'),
('20000000-0000-0000-0000-000000000355', 'word_order', 10, '{"words": ["Business", "emails", "usually", "require", "a", "formal", "register"], "correct_sentence": "Business emails usually require a formal register", "translation": "E-mails corporativos geralmente exigem um registro formal"}'),
('20000000-0000-0000-0000-000000000355', 'reading', 11, '{"passage": "This review brings together the whole subjunctive and formal structures module. Necessity is expressed with adjectives like ''essential'' and ''vital'', requests with verbs like ''insist'' and ''demand'', purpose with ''so that'' and ''lest'', and hypothetical wishes with ''wish'', ''if only'' and ''were to''. Together, these structures give writing and speech a more formal register, be it in a business email, a report or an academic essay. It''s high time you started using them naturally.", "translation": "Esta revisão reúne todo o módulo de subjuntivo e estruturas formais. Necessidade é expressa com adjetivos como ''essential'' e ''vital'', pedidos com verbos como ''insist'' e ''demand'', propósito com ''so that'' e ''lest'', e desejos hipotéticos com ''wish'', ''if only'' e ''were to''. Juntas, essas estruturas dão à escrita e à fala um registro mais formal, seja em um e-mail de negócios, um relatório ou uma redação acadêmica. Já está mais que na hora de você começar a usá-las naturalmente.", "question": "According to the text, what do these structures give to writing and speech?", "options": ["A more casual tone", "A more formal register", "A shorter length"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000355', 'listening', 12, '{"audio_text": "I wish I were more confident during presentations. It''s high time the company updated its policies. Business emails usually require a formal register.", "question": "What do business emails usually require, according to the audio?", "options": ["A formal register", "More confidence", "Updated policies"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000355', 'dictation', 13, '{"audio_text": "It''s high time the company updated its policies.", "expected": "It''s high time the company updated its policies."}'),
('20000000-0000-0000-0000-000000000355', 'typing', 14, '{"prompt_pt": "Traduza: ''Eu gostaria de ter mais tempo; já está mais que na hora de adotarmos um registro mais formal.''", "expected": "I wish I had more time; it''s high time we adopted a more formal register.", "ai_review": true}'),
('20000000-0000-0000-0000-000000000355', 'typing', 15, '{"prompt_pt": "Traduza: ''É essencial que ela insista em um registro formal, seja no e-mail, seja no relatório.''", "expected": "It is essential that she insist on a formal register, be it in the email or in the report.", "ai_review": true}');

